import java.util.*;

public class Main {
    int[] singleNumber(int[] nums) {
        int xorAll = 0;
        for (int num : nums) xorAll ^= num;                             // combined XOR of the two single values
        int lowestSetBit = xorAll & (-xorAll);                              // isolates one bit where the singles differ
        int groupA = 0, groupB = 0;
        for (int num : nums) {
            if ((num & lowestSetBit) != 0) {
                groupA ^= num;                                                 // this group cancels down to one single
            } else {
                groupB ^= num;                                                  // this group cancels down to the other single
            }
        }
        return new int[]{groupA, groupB};
    }

    public static void main(String[] args) {
        Main solution = new Main();
        int[] nums = {1, 2, 1, 3, 2, 5};
        int[] result = solution.singleNumber(nums);
        System.out.println(result[0] + " " + result[1]);
    }
}

